// Tree catalog — the four chronological stages of SynTutor's pipeline.
//
// Static mirror of web/content/tree_sheet.json (generated by
// scripts/tree_sheet.py) so modules that need the stage list at import time
// (achievements, progress) don't have to fetch JSON. Keep in sync with the
// generator's stage definitions.

export const TREE_SECTIONS = [
  { id: 1, title: 'Tokenizer', blurb: 'Split a sentence into tokens.' },
  { id: 2, title: 'Part-of-speech tagger', blurb: 'Tag each token (NN, VBZ, IN …).' },
  { id: 3, title: 'Constituency parser', blurb: 'Group tokens into phrase nodes.' },
  { id: 4, title: 'Rule matrix', blurb: 'Fire SynTutor’s grammar rules.' },
];

export function stageInfo(id) {
  const num = Number(id);
  return TREE_SECTIONS.find((s) => s.id === num) || null;
}
